function escJson(value){return JSON.stringify(value).replace(/</g,'\\u003c')}
function urlFor(lang){return `https://gamer-logic-hub.com/${folders[lang]?folders[lang]+'/':''}${slug}`}
function alternates(){return langs.map(l=>`<link rel="alternate" hreflang="${hreflangs[l]}" href="${urlFor(l)}">`).join('\n')+`\n<link rel="alternate" hreflang="x-default" href="${urlFor('ru')}">`}
function langSwitch(lang){return langs.map(l=>l===lang?`<span class="active" data-lang="${l}">${l==='es'?'AR':l==='tg'?'TJ':l.toUpperCase()}</span>`:`<a data-lang="${l}" href="${l==='ru'?prefixes[lang]+slug:prefixes[lang]+folders[l]+'/'+slug}">${l==='es'?'AR':l==='tg'?'TJ':l.toUpperCase()}</a>`).join('')}
function schema(lang,d){const article={"@type":"Article",headline:d.og,description:d.meta,inLanguage:hreflangs[lang],url:urlFor(lang),mainEntityOfPage:{"@type":"WebPage","@id":urlFor(lang)},datePublished:date,dateModified:date,image:`https://gamer-logic-hub.com/media/${hero}`,author:{"@type":"Organization",name:'Gamer Logic Hub',url:'https://gamer-logic-hub.com'},publisher:{"@type":"Organization",name:'Gamer Logic Hub',url:'https://gamer-logic-hub.com'},isAccessibleForFree:true};const faq={"@type":"FAQPage",inLanguage:hreflangs[lang],mainEntity:d.faqs.map(([name,text])=>({"@type":"Question",name,acceptedAnswer:{"@type":"Answer",text}}))};const defined={"@type":"DefinedTermSet",name:d.og,inLanguage:hreflangs[lang],url:urlFor(lang),hasDefinedTerm:terms.map(([id,name])=>({"@type":"DefinedTerm",name,url:`${urlFor(lang)}#${id}`}))};return escJson({"@context":"https://schema.org","@graph":[article,defined,faq]})}
function termSections(d){return slices.map(([start,end],i)=>`<section class="glossary-section" id="${categoryIds[i]}" data-term-section><div class="glossary-section-head"><span class="section-number">0${i+1}</span><div><h2>${d.cats[i][0]}</h2><p>${d.cats[i][1]}</p></div></div><div class="term-grid">${terms.slice(start,end).map(([id,name],j)=>{const idx=start+j;return `<section class="term-card" id="${id}" data-term="${name}"><h3>${name}<small>#${id}</small></h3><p>${d.defs[idx]}</p>${idx<12?`<span class="term-note"><strong>${d.noteLabel}:</strong> ${d.notes[idx]}</span>`:''}</section>`}).join('')}</div></section>`).join('')}
function page(lang,d){const p=prefixes[lang];const relatedHrefs=['article-rtp-slots.html','article-volatility.html','article-provably-fair-rng.html','article-bonus-buy-slots.html','calculator-rtp.html'];const nav=d.cats.map((c,i)=>`<a href="#${categoryIds[i]}">${i+1}</a>`).join('');return `<!doctype html>
<html lang="${hreflangs[lang]}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=5"><title>${d.title}</title><meta name="description" content="${d.meta}"><link rel="canonical" href="${urlFor(lang)}">${alternates()}<meta name="robots" content="index, follow"><meta property="og:type" content="article"><meta property="og:site_name" content="Gamer Logic Hub"><meta property="og:title" content="${d.og}"><meta property="og:description" content="${d.meta}"><meta property="og:url" content="${urlFor(lang)}"><meta property="og:locale" content="${ogLocales[lang]}"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="${d.og}"><meta name="twitter:description" content="${d.meta}"><link rel="icon" href="${p}favicon.png" type="image/png"><link rel="stylesheet" href="${p}media/slot-glossary.css?v=20260908-2"><script type="application/ld+json">${schema(lang,d)}</script></head>
<body><header><div class="header-inner"><div class="logo"><div class="logo-mark"><span><svg fill="none" height="16" viewBox="0 0 24 24" width="16" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M12 2 L20.5 7 V17 L12 22 L3.5 17 V7 Z" stroke="currentColor" stroke-width="1.6"></path><path d="M12 8 V16 M8 12 H16" stroke="currentColor" stroke-linecap="round" stroke-width="1.8"></path><circle cx="12" cy="12" fill="currentColor" r="1.6"></circle></svg></span></div><div>Gamer Logic Hub<small>${d.article}</small></div></div><nav aria-label="Navigation" class="main-nav"><a href="index.html">${d.nav[0]}</a><a class="active" href="articles.html">${d.nav[1]}</a></nav><div class="header-controls"><div aria-label="Language" class="lang-switch" role="group">${langSwitch(lang)}</div></div></div><div class="meander"></div></header>
<main><section class="hero glossary-hero narrow"><img class="glossary-hero-art" src="${p}media/${hero}" width="1536" height="1024" alt="${d.heroAlt}"><span class="eyebrow">${d.eyebrow}</span><h1>${d.h1}</h1><p class="lead">${d.lead}</p><p class="meta"><time datetime="${date}">${d.published}</time> · ${d.read}</p></section><div class="term-strip narrow"><span>RTP</span><span>RNG</span><span>WILD</span><span>SCATTER</span><span>MAX WIN</span><span>BONUS BUY</span></div>
<article class="article narrow" data-glossary><div class="lede"><strong>${d.quick}</strong> ${d.intro}</div><p>${d.personal}</p><div class="glossary-tools"><label class="glossary-search"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="11" cy="11" r="6.5" stroke="currentColor" stroke-width="1.8"></circle><path d="m16 16 4 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"></path></svg><input type="search" data-glossary-search placeholder="${d.search}" autocomplete="off"></label><span class="glossary-status" data-glossary-status data-template="${d.found}"></span><nav class="letter-nav" aria-label="Glossary sections">${nav}</nav></div><div class="empty-terms" data-glossary-empty>${d.empty}</div>${termSections(d)}
<section class="read-panel"><h2>${d.howTitle}</h2><p>${d.howIntro}</p><div class="read-steps">${d.steps.map(([a,b])=>`<div class="read-step"><b>${a}</b><span>${b}</span></div>`).join('')}</div></section>
<h2>${d.mythsTitle}</h2><div class="myths">${d.myths.map(([a,b])=>`<div class="myth"><b>${a}</b><span>${b}</span></div>`).join('')}</div><div class="callout"><strong>${d.take}</strong></div>
<section class="cta"><h2>${d.ctaTitle}</h2><p>${d.ctaText}</p><a href="simulator-slot-lab.html">${d.cta}</a></section><h2>${d.faq}</h2>${d.faqs.map(([q,a])=>`<h3>${q}</h3><p>${a}</p>`).join('')}<div class="related">${d.related.map((label,i)=>`<a href="${relatedHrefs[i]}">${label}</a>`).join('')}</div><div class="disclaimer"><strong>18+.</strong> ${d.disclaimer}</div><section class="sources"><h2>${d.sources}</h2><ul><li><a href="https://gaminglabs.com/wp-content/uploads/2021/06/GLI-19-Interactive-Gaming-Systems-v3.0-Russian.pdf" target="_blank" rel="noopener">Gaming Laboratories International — GLI-19 Interactive Gaming Systems</a></li><li><a href="https://www.gamblingcommission.gov.uk/licensees-and-businesses/guide/page/how-to-calculate-return-to-player-rtp" target="_blank" rel="noopener">UK Gambling Commission — How to calculate RTP</a></li><li><a href="https://www.gamblingcommission.gov.uk/public-and-players/guide/page/how-gambling-games-work" target="_blank" rel="noopener">UK Gambling Commission — How gambling games work</a></li></ul></section></article></main><footer>© 2026 Gamer Logic Hub.<br><a href="about.html">${d.about}</a></footer><script src="${p}media/slot-glossary.js?v=20260908-1"></script></body></html>`}

for(const lang of langs){
  const target=path.join(root,folders[lang],slug);
  const html=page(lang,data[lang]).replace('https://www.gamblingcommission.gov.uk/public-and-players/guide/page/how-gambling-games-work','https://www.gamblingcommission.gov.uk/public-and-players/guide/page/how-we-ensure-online-gambling-games-are-fair');
  fs.writeFileSync(target,html,'utf8');
  console.log(`wrote ${path.relative(root,target)}`);
}
